import java.io.BufferedInputStream;
import java.io.IOException;
import java.util.ArrayDeque;
import java.util.Queue;

public class Main {
    static class Pair {
        int location;
        int dist;

        Pair(int location, int dist) {
            this.location = location;
            this.dist = dist;
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner();
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        if (n >= m) {
            System.out.println(n - m);
        } else {
            boolean[] visited = new boolean[m + 2];
            Queue<Pair> queue = new ArrayDeque<>();

            queue.offer(new Pair(n, 0));
            visited[n] = true;

            int ans = 0;

            while (!queue.isEmpty()) {
                Pair current = queue.poll();

                if (current.location == m) {
                    ans = current.dist;
                    break;
                }

                int doubled = current.location * 2;
                if (doubled <= m + 1 && !visited[doubled]) {
                    queue.offer(new Pair(doubled, current.dist + 1));
                    visited[doubled] = true;
                }

                int previous = current.location - 1;
                if (previous >= 0 && !visited[previous]) {
                    queue.offer(new Pair(previous, current.dist + 1));
                    visited[previous] = true;
                }
            }

            System.out.println(ans);
        }
    }

    static class FastScanner {
        private final BufferedInputStream input = new BufferedInputStream(System.in);
        private final byte[] buffer = new byte[1 << 16];
        private int position;
        private int length;

        private int read() throws IOException {
            if (position >= length) {
                length = input.read(buffer);
                position = 0;
                if (length == -1) {
                    return -1;
                }
            }
            return buffer[position++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int value = 0;
            while (c > ' ') {
                value = value * 10 + c - '0';
                c = read();
            }
            return value * sign;
        }
    }
}

